int[][] acts = {{1, 4}, {2, 3}, {3, 5}};   // {start, finish}
int best = 0;
for (int i = 1; i < acts.length; i++)
    if (acts[i][1] < acts[best][1]) best = i;
System.out.println(acts[best][0] + "-" + acts[best][1]);

int[][] items = {{60, 10}, {100, 20}, {120, 30}};   // {value, weight}
int best = 0;
for (int i = 1; i < items.length; i++)
    if (items[i][0] * items[best][1] > items[best][0] * items[i][1]) best = i;
System.out.println(items[best][0] + "/" + items[best][1]);

int[][] ev = {{1, 1}, {2, 1}, {3, -1}, {4, -1}, {6, 1}, {8, -1}};
int cur = 0, max = 0;
for (int[] e : ev) {
    cur += e[1];
    max = Math.max(max, cur);
}
System.out.println(max);

int[][] a = {{1, 4}, {3, 5}, {0, 6}, {5, 7}, {8, 9}};   // sorted by finish
int count = 1, last = 0;
for (int i = 1; i < a.length; i++)
    if (a[i][0] >= a[last][1]) { count++; last = i; }
System.out.println(count);

int[] coins = {5, 2, 1};
int amount = 23, count = 0;
for (int c : coins) {
    count += amount / c;
    amount %= c;
}
System.out.println(count + " " + amount);

int[] coins = {4, 3, 1};   // non-canonical system
int amount = 6, count = 0;
for (int c : coins) {
    count += amount / c;
    amount %= c;
}
System.out.println(count + " " + amount);

int[][] items = {{60, 10}, {100, 20}, {120, 30}};   // {value, weight}
int cap = 50;
double value = 0;
for (int[] it : items) {
    int take = Math.min(it[1], cap);
    value += take * (double) it[0] / it[1];
    cap -= take;
}
System.out.println(value);
